import { defineConfig } from 'drizzle-kit';
import * as dotenv from 'dotenv';

// 1. Explicitly force it to load the .env file in this folder
dotenv.config();

// 2. Safety check! This will warn you if it can't find the .env file
if (!process.env.DATABASE_URL) {
  throw new Error("❌ DATABASE_URL is missing! Make sure your .env file is inside apps/server");
}

export default defineConfig({
  schema: './src/db/schema.ts',
  out: './drizzle',
  dialect: 'postgresql',
  dbCredentials: {
    url: process.env.DATABASE_URL,
  },
});